CREATE OR REPLACE FUNCTION public.manage_driver_incident(_id uuid,_action text,_message text DEFAULT NULL,_status text DEFAULT NULL,_priority text DEFAULT NULL,_assigned_to uuid DEFAULT NULL,_internal boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.incidents; manager boolean; actor text; BEGIN
manager:=public.can_manage_operation_board(auth.uid()); SELECT * INTO i FROM public.incidents WHERE id=_id FOR UPDATE; IF auth.uid() IS NULL OR NOT FOUND OR NOT public.can_access_incident(_id,auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
IF i.closed_at IS NOT NULL THEN RAISE EXCEPTION 'Incident closed'; END IF;
IF _action NOT IN ('message','guidance','request_info','acknowledge','status','priority','assign','resolve','close') OR length(coalesce(_message,''))>4000 THEN RAISE EXCEPTION 'Invalid action'; END IF;
IF NOT manager AND (_action<>'message' OR _internal OR _status IS NOT NULL OR _priority IS NOT NULL OR _assigned_to IS NOT NULL) THEN RAISE EXCEPTION 'Driver can only respond'; END IF;
IF _action IN ('message','guidance','request_info','resolve','close') AND length(trim(coalesce(_message,'')))<3 THEN RAISE EXCEPTION 'Message required'; END IF;
IF _action='status' AND (_status IS NULL OR _status NOT IN ('received','analysis','awaiting_driver','handling') OR i.resolved_at IS NOT NULL) THEN RAISE EXCEPTION 'Invalid status'; END IF;
IF _action='priority' AND (_priority IS NULL OR _priority NOT IN ('informative','attention','high','critical')) THEN RAISE EXCEPTION 'Invalid priority'; END IF;
IF _action='assign' AND _assigned_to IS NOT NULL AND NOT public.can_manage_operation_board(_assigned_to) THEN RAISE EXCEPTION 'Invalid assignee'; END IF;
IF _action='close' AND i.resolved_at IS NULL THEN RAISE EXCEPTION 'Resolve before closure'; END IF;
UPDATE public.incidents SET workflow_status=CASE WHEN _action='acknowledge' THEN 'received' WHEN _action='request_info' THEN 'awaiting_driver' WHEN _action='guidance' THEN 'handling' WHEN _action='status' THEN _status WHEN _action='resolve' THEN 'resolved' WHEN _action='close' THEN 'closed' WHEN NOT manager AND workflow_status='awaiting_driver' THEN 'analysis' ELSE workflow_status END, priority=CASE WHEN _action='priority' THEN _priority ELSE priority END,severity=CASE WHEN _action='priority' THEN CASE WHEN _priority IN ('high','critical') THEN 'high' WHEN _priority='informative' THEN 'low' ELSE 'medium' END ELSE severity END,assigned_to=CASE WHEN _action='assign' THEN _assigned_to ELSE assigned_to END,acknowledged_at=CASE WHEN manager THEN coalesce(acknowledged_at,now()) ELSE acknowledged_at END,acknowledged_by=CASE WHEN manager THEN coalesce(acknowledged_by,auth.uid()) ELSE acknowledged_by END,resolved_at=CASE WHEN _action='resolve' THEN now() ELSE resolved_at END,closed_at=CASE WHEN _action='close' THEN now() ELSE closed_at END,closed_by=CASE WHEN _action='close' THEN auth.uid() ELSE closed_by END WHERE id=_id;
SELECT coalesce(full_name,'Usuário') INTO actor FROM public.profiles WHERE id=auth.uid();
INSERT INTO public.incident_updates(incident_id,actor_id,actor_name,action,message,internal,metadata) VALUES(_id,auth.uid(),coalesce(actor,'Usuário'),_action,nullif(trim(_message),''),_internal,jsonb_build_object('status',_status,'priority',_priority,'assigned_to',_assigned_to));
INSERT INTO public.order_events(order_id,event_type,actor_id,payload) VALUES(i.order_id,'driver_incident_'||_action,auth.uid(),jsonb_build_object('incident_id',i.id,'internal',_internal));
IF NOT _internal THEN IF manager AND i.reported_by IS NOT NULL AND i.reported_by IS DISTINCT FROM auth.uid() THEN INSERT INTO public.notifications(user_id,type,title,body,data) VALUES(i.reported_by,'driver_incident_update','Atualização da ocorrência',coalesce(nullif(trim(_message),''),'A operação atualizou sua ocorrência.'),jsonb_build_object('incident_id',i.id,'order_id',i.order_id)); ELSIF NOT manager THEN INSERT INTO public.notifications(user_id,type,title,body,data) SELECT DISTINCT user_id,'driver_incident_update','Resposta do motorista',left(_message,500),jsonb_build_object('incident_id',i.id,'order_id',i.order_id) FROM public.user_roles WHERE role IN ('admin','logistics','supervisor','operacional'); END IF; END IF; END; $$;
REVOKE ALL ON FUNCTION public.manage_driver_incident(uuid,text,text,text,text,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.manage_driver_incident(uuid,text,text,text,text,uuid,boolean) TO authenticated;